import json,gzip,collections,math,sys
import pyBigWig
unknown=collections.defaultdict(list); ends=collections.defaultdict(list)
with gzip.open('inputs/reverse.encode.q1.tsv.gz','rt') as fh:
 for line in fh:
  c,s,e,v=line.rstrip().split('\\t'); unknown[c].append(float(v)); ends[c].append(int(e))
candidates=['ENCSR597URK','ENCSR541PUY','ENCSR296TFH','ENCSR058ELM','ENCSR531UVE','ENCSR420HOT']
bam=json.load(open('work/encode_dnase_grch38_bams_embedded.json'))['@graph']
analysis={}; N={}; files={}; summary={}
for f in bam:
 exp=f.get('dataset','').split('/')[2] if f.get('dataset') else ''
 if exp not in candidates: continue
 an=f.get('analyses') or []
 if an and an[0].get('pipeline_version')=='3.0.0-alpha.2':
  analysis[exp]=an[0]['@id']; files.setdefault(exp,[]).append(f['accession']); summary[exp]=f.get('simple_biosample_summary')
  for qm in f.get('quality_metrics',[]):
   if 'SamtoolsFlagstatsQualityMetric' in qm.get('@type',[]): N[exp]=N.get(exp,0)+int(qm.get('total') or 0)
bwdata=json.load(open('work/encode_dnase_grch38_bigwigs.json'))['@graph']
by=collections.defaultdict(list)
for f in bwdata:
 exp=f.get('dataset','').split('/')[2] if f.get('dataset') else ''
 if exp in candidates and f.get('file_format_type') is None and f.get('analyses') and f['analyses'][0]==analysis.get(exp): by[exp].append(f)
def corr(x,y):
 n=len(x); mx=sum(x)/n; my=sum(y)/n
 vx=sum((a-mx)**2 for a in x); vy=sum((b-my)**2 for b in y); cov=sum((a-mx)*(b-my) for a,b in zip(x,y))
 return cov/math.sqrt(vx*vy)
for exp in candidates:
 rep_vecs=[]; names=[]; master_unk=None
 for f in by[exp]:
  url=f.get('cloud_metadata',{}).get('url') or 'https://www.encodeproject.org'+f['href']
  bw=pyBigWig.open(url); chrs=bw.chroms(); vals_all=[]; unk_all=[]
  for c in unknown:
   if c not in chrs: continue
   m=0
   for e in ends[c]:
    if e <= chrs[c]: m+=1
    else: break
   if m<=0: continue
   try:
    vals=bw.stats(c,0,m*10000,nBins=m,type='mean')
   except Exception as e:
    print('skip',exp,f['accession'],c,chrs.get(c),m,m*10000,e,file=sys.stderr)
    continue
   vals_all.extend(0 if v is None else v for v in vals); unk_all.extend(unknown[c][:m])
  bw.close(); rep_vecs.append(vals_all); names.append(f['accession']); master_unk=unk_all
 if not rep_vecs: continue
 minlen=min(len(v) for v in rep_vecs)
 avg=[sum(v[i] for v in rep_vecs)/len(rep_vecs) for i in range(minlen)]
 unk=master_unk[:minlen]
 print(exp,'N',N.get(exp),'files',files.get(exp),'bw',names,'n_bins',len(avg),'corr',round(corr(unk,avg),6),'summary',summary.get(exp))
